-- DBA 전달용. 대상 DB/서비스는 Q1과 사진의 기존 AIDP 연결을 대조합니다.
-- 각 Q를 별도로 실행하는 SELECT 전용 문서입니다. NULL/0행은 확인불가일 수 있습니다.
-- quota 행 없음은 무제한/0 판정이 아닙니다. UNLIMITED TABLESPACE 직접/역할 권한은 DBA가 별도 확인합니다.
-- _1 외 기존 표 용량은 Q3에 없고 계정 전체 할당은 Q4에 포함됩니다.
-- 운영 여유/물리 디스크/자동확장 성공은 별도 확인. 임의 DDL/정리 명령 없음.

-- Q1 실제 접속자/DB 확인
SELECT SYS_CONTEXT('USERENV','SESSION_USER') AS LOGIN_USER, SYS_CONTEXT('USERENV','CURRENT_SCHEMA') AS CURRENT_SCHEMA, SYS_CONTEXT('USERENV','DB_UNIQUE_NAME') AS DB_NAME, SYS_CONTEXT('USERENV','SERVICE_NAME') AS SERVICE_NAME FROM DUAL;

-- Q2 현재 _1 대상 17개와 과거 통계; 실제 COUNT 아님
WITH wanted AS (SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_VER_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_UNIT_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_BLK_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRC_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_ROW_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_CHNL_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_POST_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_HEAD_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_ANC_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_ITEM_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_HEAD_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_RUN_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_REC_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_BODY_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_EXEC_ST_A_1' AS TABLE_NAME FROM DUAL) SELECT w.OWNER,w.TABLE_NAME,t.TABLESPACE_NAME,
t.NUM_ROWS AS STATS_ROWS,t.AVG_ROW_LEN,t.BLOCKS,t.PARTITIONED,t.IOT_TYPE,t.CLUSTER_NAME,
t.SEGMENT_CREATED,TO_CHAR(t.LAST_ANALYZED,'YYYY-MM-DD HH24:MI:SS') AS STATS_AT,
CASE WHEN t.TABLE_NAME IS NULL THEN 'NOT_VISIBLE_OR_ABSENT' ELSE 'VISIBLE' END AS VISIBILITY
FROM wanted w LEFT JOIN ALL_TABLES t ON t.OWNER=w.OWNER AND t.TABLE_NAME=w.TABLE_NAME
ORDER BY w.OWNER,w.TABLE_NAME;

-- Q3 _1 테이블+인덱스+LOB 물리 할당; 일반 테이블 구조만
WITH wanted AS (SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_VER_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_UNIT_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_BLK_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRC_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_ROW_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_CHNL_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_POST_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_HEAD_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_ANC_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_ITEM_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_HEAD_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_RUN_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_REC_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_BODY_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_EXEC_ST_A_1' AS TABLE_NAME FROM DUAL), targets AS (
SELECT t.* FROM ALL_TABLES t JOIN wanted w
ON t.OWNER=w.OWNER AND t.TABLE_NAME=w.TABLE_NAME), regular AS (
SELECT * FROM targets WHERE PARTITIONED='NO' AND IOT_TYPE IS NULL AND CLUSTER_NAME IS NULL),
mapped AS (
SELECT OWNER AS TABLE_OWNER,TABLE_NAME,OWNER AS SEGMENT_OWNER,TABLE_NAME AS SEGMENT_NAME FROM regular
UNION SELECT i.TABLE_OWNER,i.TABLE_NAME,i.OWNER,i.INDEX_NAME FROM ALL_INDEXES i JOIN regular t
ON i.TABLE_OWNER=t.OWNER AND i.TABLE_NAME=t.TABLE_NAME WHERE i.PARTITIONED='NO'
UNION SELECT l.OWNER,l.TABLE_NAME,l.OWNER,l.SEGMENT_NAME FROM ALL_LOBS l JOIN regular t
ON l.OWNER=t.OWNER AND l.TABLE_NAME=t.TABLE_NAME
UNION SELECT l.OWNER,l.TABLE_NAME,l.OWNER,l.INDEX_NAME FROM ALL_LOBS l JOIN regular t
ON l.OWNER=t.OWNER AND l.TABLE_NAME=t.TABLE_NAME) SELECT m.TABLE_OWNER AS OWNER,m.TABLE_NAME,
s.TABLESPACE_NAME,s.SEGMENT_TYPE,SUM(s.BYTES) AS ALLOCATED_BYTES
FROM mapped m JOIN DBA_SEGMENTS s ON s.OWNER=m.SEGMENT_OWNER AND s.SEGMENT_NAME=m.SEGMENT_NAME
GROUP BY m.TABLE_OWNER,m.TABLE_NAME,s.TABLESPACE_NAME,s.SEGMENT_TYPE
ORDER BY m.TABLE_OWNER,m.TABLE_NAME,s.TABLESPACE_NAME,s.SEGMENT_TYPE;

-- Q4 소유자 SIDDS/SIDDA의 해당 tablespace 전체 계정 사용량/등록 한도
WITH wanted AS (SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_VER_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_UNIT_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_BLK_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRC_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_ROW_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_CHNL_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_POST_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_HEAD_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_ANC_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_ITEM_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_HEAD_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_RUN_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_REC_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_BODY_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_EXEC_ST_A_1' AS TABLE_NAME FROM DUAL), targets AS (
SELECT t.* FROM ALL_TABLES t JOIN wanted w
ON t.OWNER=w.OWNER AND t.TABLE_NAME=w.TABLE_NAME), target_ts AS (
SELECT OWNER,TABLESPACE_NAME FROM targets WHERE TABLESPACE_NAME IS NOT NULL
UNION SELECT i.TABLE_OWNER,i.TABLESPACE_NAME FROM ALL_INDEXES i JOIN targets t
ON i.TABLE_OWNER=t.OWNER AND i.TABLE_NAME=t.TABLE_NAME WHERE i.TABLESPACE_NAME IS NOT NULL
UNION SELECT l.OWNER,l.TABLESPACE_NAME FROM ALL_LOBS l JOIN targets t
ON l.OWNER=t.OWNER AND l.TABLE_NAME=t.TABLE_NAME WHERE l.TABLESPACE_NAME IS NOT NULL) SELECT x.OWNER,x.TABLESPACE_NAME,q.BYTES AS CHARGED_BYTES,
q.MAX_BYTES AS QUOTA_BYTES,CASE WHEN q.USERNAME IS NULL THEN 'NO_QUOTA_ROW_NOT_CONCLUSIVE'
WHEN q.MAX_BYTES=-1 THEN 'REGISTERED_UNLIMITED' ELSE 'REGISTERED_LIMIT' END AS QUOTA_STATE
FROM target_ts x LEFT JOIN DBA_TS_QUOTAS q ON q.USERNAME=x.OWNER AND q.TABLESPACE_NAME=x.TABLESPACE_NAME
ORDER BY x.OWNER,x.TABLESPACE_NAME;

-- Q5 공유 tablespace 파일/미할당 extent/자동확장 설정
WITH wanted AS (SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_VER_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_UNIT_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_DOC_BLK_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRC_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_ROW_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_SRCH_CHNL_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_POST_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_HEAD_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_G19_ONTL_ANC_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_POST_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_ITEM_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDS' AS OWNER,'LGL_G19_VCTR_HEAD_S_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_RUN_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_REC_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_AGT_BODY_A_1' AS TABLE_NAME FROM DUAL UNION ALL SELECT 'SIDDA' AS OWNER,'LGL_EXEC_ST_A_1' AS TABLE_NAME FROM DUAL), targets AS (
SELECT t.* FROM ALL_TABLES t JOIN wanted w
ON t.OWNER=w.OWNER AND t.TABLE_NAME=w.TABLE_NAME), target_ts AS (
SELECT OWNER,TABLESPACE_NAME FROM targets WHERE TABLESPACE_NAME IS NOT NULL
UNION SELECT i.TABLE_OWNER,i.TABLESPACE_NAME FROM ALL_INDEXES i JOIN targets t
ON i.TABLE_OWNER=t.OWNER AND i.TABLE_NAME=t.TABLE_NAME WHERE i.TABLESPACE_NAME IS NOT NULL
UNION SELECT l.OWNER,l.TABLESPACE_NAME FROM ALL_LOBS l JOIN targets t
ON l.OWNER=t.OWNER AND l.TABLE_NAME=t.TABLE_NAME WHERE l.TABLESPACE_NAME IS NOT NULL), names AS (SELECT DISTINCT TABLESPACE_NAME FROM target_ts),
files AS (SELECT d.TABLESPACE_NAME,SUM(d.BYTES) AS FILE_BYTES,
SUM(CASE WHEN d.AUTOEXTENSIBLE='YES' THEN GREATEST(d.MAXBYTES-d.BYTES,0) ELSE 0 END) AS AUTO_GROW_BYTES,
SUM(CASE WHEN d.ONLINE_STATUS<>'ONLINE' THEN 1 ELSE 0 END) AS NOT_ONLINE_FILES
FROM DBA_DATA_FILES d JOIN names n ON n.TABLESPACE_NAME=d.TABLESPACE_NAME GROUP BY d.TABLESPACE_NAME),
free AS (SELECT f.TABLESPACE_NAME,SUM(f.BYTES) AS FREE_BYTES,MAX(f.BYTES) AS MAX_FREE_EXTENT_BYTES
FROM DBA_FREE_SPACE f JOIN names n ON n.TABLESPACE_NAME=f.TABLESPACE_NAME GROUP BY f.TABLESPACE_NAME)
SELECT n.TABLESPACE_NAME,d.FILE_BYTES,d.AUTO_GROW_BYTES,d.NOT_ONLINE_FILES,
f.FREE_BYTES,f.MAX_FREE_EXTENT_BYTES FROM names n LEFT JOIN files d ON d.TABLESPACE_NAME=n.TABLESPACE_NAME
LEFT JOIN free f ON f.TABLESPACE_NAME=n.TABLESPACE_NAME ORDER BY n.TABLESPACE_NAME;

